   KRange (eaddz e_atrandom 16) 0x7fff800000c0 0x800000000000; KRange e_atr8 0xFFFF0000001 0xFFFFFFFFFE9;
   KRange e_sp0 0x7fff80000000 0x7fffffffff40;
